/* Yongjia farm produce site — progressive enhancement only.
   Language switching is handled by the assembler helper; this file adds
   reveal-on-scroll, mobile nav toggle and a small catalogue filter. */
(function () {
  'use strict';

  var root = document.documentElement;
  root.classList.add('js-ready');

  /* ---- mobile navigation ---- */
  var navToggle = document.getElementById('navToggle');
  var navList = document.getElementById('navList');
  if (navToggle && navList) {
    navToggle.addEventListener('click', function () {
      var open = navList.classList.toggle('is-open');
      navToggle.setAttribute('aria-expanded', open ? 'true' : 'false');
    });
    navList.addEventListener('click', function (event) {
      if (event.target.closest('a')) {
        navList.classList.remove('is-open');
        navToggle.setAttribute('aria-expanded', 'false');
      }
    });
  }

  /* ---- reveal on scroll (content stays readable without JS) ---- */
  var revealItems = Array.prototype.slice.call(document.querySelectorAll('.reveal'));
  var reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  if (!('IntersectionObserver' in window) || reduceMotion) {
    revealItems.forEach(function (el) { el.classList.add('is-visible'); });
  } else {
    var observer = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (entry.isIntersecting) {
          entry.target.classList.add('is-visible');
          observer.unobserve(entry.target);
        }
      });
    }, { rootMargin: '0px 0px -8% 0px', threshold: 0.12 });
    revealItems.forEach(function (el) { observer.observe(el); });
  }

  /* ---- catalogue filter ---- */
  var filterButtons = Array.prototype.slice.call(document.querySelectorAll('.filter-btn'));
  var productCards = Array.prototype.slice.call(document.querySelectorAll('[data-category]'));
  if (filterButtons.length && productCards.length) {
    filterButtons.forEach(function (btn) {
      btn.addEventListener('click', function () {
        var key = btn.getAttribute('data-filter');
        filterButtons.forEach(function (b) {
          var active = b === btn;
          b.classList.toggle('is-active', active);
          b.setAttribute('aria-pressed', active ? 'true' : 'false');
        });
        productCards.forEach(function (card) {
          var match = key === 'all' || card.getAttribute('data-category') === key;
          card.hidden = !match;
        });
      });
    });
  }

  /* ---- year stamp ---- */
  var yearNodes = document.querySelectorAll('[data-year]');
  var year = String(new Date().getFullYear());
  Array.prototype.forEach.call(yearNodes, function (node) { node.textContent = year; });
})();
